using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Grasshopper.Kernel;

namespace BenchPlugin
{
    public class AsyncStatsComponent : GH_Component
    {
        private CancellationTokenSource _cts;
        private List<double> _pendingInput;
        private List<double> _resultInput;
        private double _mean, _stdDev;

        public AsyncStatsComponent()
            : base("Async Stats", "AsyncStats", "Computes mean and standard deviation of a list of numbers asynchronously", "Bench", "Data")
        {
        }

        public override Guid ComponentGuid => new Guid("c4a92f06-1d38-4e7b-a5c1-8b0e3f6d2a79");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddNumberParameter("Values", "V", "Numbers to analyse", GH_ParamAccess.list);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Mean", "M", "Arithmetic mean", GH_ParamAccess.item);
            pManager.AddNumberParameter("StdDev", "S", "Population standard deviation", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var values = new List<double>();
            if (!DA.GetDataList(0, values)) return;
            if (values.Count == 0) return;

            // Result of a previous run for identical inputs is ready.
            if (_resultInput != null && _resultInput.SequenceEqual(values))
            {
                DA.SetData(0, _mean);
                DA.SetData(1, _stdDev);
                return;
            }

            // Same inputs already being computed.
            if (_pendingInput != null && _pendingInput.SequenceEqual(values)) return;

            // Inputs changed: cancel the previous computation.
            _cts?.Cancel();
            _cts = new CancellationTokenSource();
            _pendingInput = values;
            _resultInput = null;

            var cts = _cts;
            var token = cts.Token;
            var data = values;
            var doc = OnPingDocument();

            Task.Run(() =>
            {
                double mean = data.Sum() / data.Count;
                double sumSq = 0;
                for (int i = 0; i < data.Count; i++)
                {
                    token.ThrowIfCancellationRequested();
                    double d = data[i] - mean;
                    sumSq += d * d;
                }
                return (mean, Math.Sqrt(sumSq / data.Count));
            }, token).ContinueWith(t =>
            {
                if (t.IsCanceled || t.IsFaulted || token.IsCancellationRequested) return;
                _mean = t.Result.Item1;
                _stdDev = t.Result.Item2;
                _resultInput = data;
                _pendingInput = null;
                doc?.ScheduleSolution(5, d => ExpireSolution(false));
            }, TaskScheduler.Default);
        }
    }
}
EOF
